import { describe, expect, it } from 'vitest';
import { collectSheetRules } from './collectSheetRules';

const parseDoc = (svg: string) =>
  new DOMParser().parseFromString(svg, 'text/xml');

describe('collectSheetRules', () => {
  it('collects rules from a single style element', () => {
    const doc = parseDoc(`<svg xmlns="http://www.w3.org/2000/svg">
      <style>.blue { fill: blue; }</style>
    </svg>`);
    expect(collectSheetRules(doc)).toEqual({
      '.blue': { fill: 'blue' },
    });
  });

  it('collects rules declared across more than one style element', () => {
    const doc = parseDoc(`<svg xmlns="http://www.w3.org/2000/svg">
      <style>.blue { fill: blue; }</style>
      <style>.red { fill: red; }</style>
    </svg>`);
    expect(collectSheetRules(doc)).toEqual({
      '.blue': { fill: 'blue' },
      '.red': { fill: 'red' },
    });
  });

  it('preserves colons inside a declaration value, e.g. a paint server url', () => {
    const doc = parseDoc(`<svg xmlns="http://www.w3.org/2000/svg">
      <style>.red { fill: url(https://example.com/paint.svg#swatch); }</style>
    </svg>`);
    expect(collectSheetRules(doc)).toEqual({
      '.red': { fill: 'url(https://example.com/paint.svg#swatch)' },
    });
  });
});

